-- Default variant for every product
SELECT id, CONCAT(sku, '-STD'), CONCAT(dial_color, ' dial / ', strap_material), dial_color, strap_material, 0, TRUE, FALSE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6) FROM products;

-- Additional variants

-- Inventory for every variant (varied stock levels; one sold-out and one low-stock example)
SELECT id, MOD(id * 7, 18) + 4, 0, 5, CURRENT_TIMESTAMP(6) FROM product_variants;
UPDATE inventory SET quantity_on_hand = 0 WHERE variant_id = (SELECT id FROM product_variants WHERE sku = 'VER-RB42-STD');
UPDATE inventory SET quantity_on_hand = 2 WHERE variant_id = (SELECT id FROM product_variants WHERE sku = 'AUR-HC38-STD');

SELECT variant_id, 'STOCK_IN', quantity_on_hand, quantity_on_hand, 0, 'SEED', 'Opening stock', CURRENT_TIMESTAMP(6) FROM inventory WHERE quantity_on_hand > 0;

-- Product images (primary + gallery)

-- Extended specifications
SELECT id, 'Power reserve', CASE WHEN movement_type = 'AUTOMATIC' THEN '70 hours' WHEN movement_type = 'MANUAL' THEN '60 hours' WHEN movement_type = 'SOLAR' THEN '6 months (full charge)' ELSE '3-year battery' END, 1 FROM products;
SELECT id, 'Case thickness', CONCAT(ROUND(case_diameter_mm / 3.6, 1), ' mm'), 2 FROM products;
SELECT id, 'Lug width', CONCAT(CASE WHEN case_diameter_mm >= 40 THEN 20 WHEN case_diameter_mm >= 36 THEN 19 ELSE 16 END, ' mm'), 3 FROM products;

