INSERT INTO brands (name, slug, description, country_of_origin, founded_year, logo_url, banner_url, featured, active, deleted, created_at, updated_at) VALUES
('Aurelian Genève', 'aurelian', 'A Genevan maison devoted to haute horlogerie since 1891. Hand-finished movements, guilloché dials and restrained, timeless cases.', 'Switzerland', 1891, NULL, 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=1600&q=80', TRUE, TRUE, FALSE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)),
('Nordhavn', 'nordhavn', 'Scandinavian tool watches distilled to their essentials: legible, robust and quietly beautiful.', 'Denmark', 2009, NULL, 'https://images.unsplash.com/photo-1524592094714-0f0654e20314?w=1600&q=80', TRUE, TRUE, FALSE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)),
('Maison Vérac', 'maison-verac', 'Parisian chronograph specialists with a motorsport soul and nearly a century of timing heritage.', 'France', 1924, NULL, 'https://images.unsplash.com/photo-1522312346375-d1a52e2b99b3?w=1600&q=80', TRUE, TRUE, FALSE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)),
('Kestrel & Co.', 'kestrel', 'British aviation instruments for the wrist, born from cockpit clocks built for the RAF.', 'United Kingdom', 1962, NULL, 'https://images.unsplash.com/photo-1542496658-e33a6d0d50f6?w=1600&q=80', FALSE, TRUE, FALSE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)),
('Halden Marine', 'halden', 'Professional dive watches engineered on the Norwegian coast and tested in the North Sea.', 'Norway', 1978, NULL, 'https://images.unsplash.com/photo-1547996160-81dfa63595aa?w=1600&q=80', TRUE, TRUE, FALSE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)),
('Sora Tokei', 'sora-tokei', 'Japanese precision and seasonal dials inspired by the sky over Nagano.', 'Japan', 1955, NULL, 'https://images.unsplash.com/photo-1533139502658-0198f920d8e8?w=1600&q=80', FALSE, TRUE, FALSE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6));
INSERT INTO categories (name, slug, description, image_url, display_order, active, deleted, created_at, updated_at) VALUES
('Dress Watches', 'dress', 'Slim, elegant pieces for the occasions that matter.', 'https://images.unsplash.com/photo-1587836374828-4dbafa94cf0e?w=1200&q=80', 1, TRUE, FALSE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)),
('Dive Watches', 'dive', 'Uncompromising water resistance, unidirectional bezels and luminous legibility.', 'https://images.unsplash.com/photo-1548171915-e79a380a2a4b?w=1200&q=80', 2, TRUE, FALSE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)),
('Chronographs', 'chronograph', 'Stopwatch complications with racing and aviation heritage.', 'https://images.unsplash.com/photo-1539874754764-5a96559165b0?w=1200&q=80', 3, TRUE, FALSE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)),
('Pilot & Field', 'pilot-field', 'Rugged instruments with maximum legibility.', 'https://images.unsplash.com/photo-1612817159949-195b6eb9e31a?w=1200&q=80', 4, TRUE, FALSE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)),
('GMT & Travel', 'gmt-travel', 'Track a second time zone wherever you land.', 'https://images.unsplash.com/photo-1614164185128-e4ec99c436d7?w=1200&q=80', 5, TRUE, FALSE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)),
('Everyday Watches', 'everyday', 'Versatile watches that go from desk to weekend.', 'https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?w=1200&q=80', 6, TRUE, FALSE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6));
INSERT INTO products (brand_id, category_id, name, slug, model_name, sku, short_description, description, movement_type, case_diameter_mm, case_material, water_resistance_m, crystal_type, strap_material, dial_color, case_color, gender, warranty_months, regular_price, selling_price, discount_percent, status, featured, new_arrival, best_seller, sold_count, created_at, updated_at) VALUES
((SELECT id FROM brands WHERE slug='aurelian'), (SELECT id FROM categories WHERE slug='dress'), 'Heritage Classique 38', 'aurelian-heritage-classique-38', 'HC-38', 'AUR-HC38', 'An 18K rose-gold dress watch with a hand-guilloché silver dial.', 'The Heritage Classique distils 130 years of Genevan craft into a 38 mm case of 18K rose gold. Its silver dial is hand-engraved with a barleycorn guilloché, framed by applied dauphine hands. Inside beats the in-house calibre A-21 with 72 hours of power reserve, visible through a sapphire case back.', 'AUTOMATIC', 38.00, '18K Rose Gold', 30, 'Sapphire', 'Alligator Leather', 'Silver', 'Rose Gold', 'MEN', 60, 685000.00, 685000.00, 0.00, 'ACTIVE', TRUE, FALSE, FALSE, 4, TIMESTAMPADD(DAY, -120, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6)),
((SELECT id FROM brands WHERE slug='aurelian'), (SELECT id FROM categories WHERE slug='dress'), 'Lune Moonphase 40', 'aurelian-lune-moonphase-40', 'LM-40', 'AUR-LM40', 'A midnight-blue aventurine dial with a precise moonphase.', 'A poetic complication rendered with engineering rigour: the Lune moonphase is accurate to one day every 122 years. The midnight-blue dial glitters with aventurine, while the polished steel case keeps the piece wearable every day.', 'AUTOMATIC', 40.00, 'Stainless Steel', 50, 'Sapphire', 'Leather', 'Midnight Blue', 'Steel', 'MEN', 60, 412000.00, 389000.00, 5.58, 'ACTIVE', TRUE, FALSE, TRUE, 21, TIMESTAMPADD(DAY, -200, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6)),
((SELECT id FROM brands WHERE slug='aurelian'), (SELECT id FROM categories WHERE slug='dress'), 'Petite Seconde 34', 'aurelian-petite-seconde-34', 'PS-34', 'AUR-PS34', 'A hand-wound 34 mm classic with small seconds.', 'Compact, refined and hand-wound, the Petite Seconde celebrates the ritual of winding a watch each morning. The ivory enamel dial features a sunken small-seconds sub-dial and blued steel hands.', 'MANUAL', 34.00, 'Stainless Steel', 30, 'Sapphire', 'Leather', 'Ivory', 'Steel', 'WOMEN', 60, 298000.00, 298000.00, 0.00, 'ACTIVE', FALSE, TRUE, FALSE, 3, TIMESTAMPADD(DAY, -12, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6)),
((SELECT id FROM brands WHERE slug='nordhavn'), (SELECT id FROM categories WHERE slug='pilot-field'), 'Field 39', 'nordhavn-field-39', 'FD-39', 'NOR-FD39', 'A legible 39 mm field watch with 100 m water resistance.', 'Built for the trail and the office alike, the Field 39 pairs a matte dial and Super-LumiNova numerals with a robust automatic movement. Screw-down crown, sapphire crystal and quick-release straps come standard.', 'AUTOMATIC', 39.00, 'Stainless Steel', 100, 'Sapphire', 'Canvas', 'Black', 'Steel', 'UNISEX', 24, 64500.00, 58050.00, 10.00, 'ACTIVE', FALSE, FALSE, TRUE, 58, TIMESTAMPADD(DAY, -260, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6)),
((SELECT id FROM brands WHERE slug='nordhavn'), (SELECT id FROM categories WHERE slug='everyday'), 'Minimal 36', 'nordhavn-minimal-36', 'MN-36', 'NOR-MN36', 'An ultra-thin quartz watch with a Milanese mesh bracelet.', 'Just 6.8 mm thin, the Minimal 36 is Scandinavian design at its purest: an uncluttered white dial, slender baton hands and a supple Milanese mesh bracelet.', 'QUARTZ', 36.00, 'Stainless Steel', 50, 'Sapphire', 'Mesh Steel', 'White', 'Silver', 'UNISEX', 24, 28900.00, 24565.00, 15.00, 'ACTIVE', FALSE, TRUE, FALSE, 34, TIMESTAMPADD(DAY, -20, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6)),
((SELECT id FROM brands WHERE slug='maison-verac'), (SELECT id FROM categories WHERE slug='chronograph'), 'Chronographe Panda 40', 'maison-verac-chronographe-panda-40', 'CP-40', 'VER-CP40', 'The iconic panda-dial racing chronograph.', 'White dial, black sub-dials, tachymeter bezel: the Chronographe Panda is the definitive racing chronograph. Its column-wheel automatic calibre delivers crisp pusher action and 60 hours of reserve.', 'AUTOMATIC', 40.00, 'Stainless Steel', 100, 'Sapphire', 'Steel Bracelet', 'White', 'Steel', 'MEN', 36, 245000.00, 229000.00, 6.53, 'ACTIVE', TRUE, FALSE, TRUE, 27, TIMESTAMPADD(DAY, -300, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6)),
((SELECT id FROM brands WHERE slug='maison-verac'), (SELECT id FROM categories WHERE slug='chronograph'), 'Racing Bicompax 42', 'maison-verac-racing-bicompax-42', 'RB-42', 'VER-RB42', 'A hand-wound titanium bicompax in racing green.', 'A limited series honouring the 1958 endurance season. Lightweight grade 5 titanium, a racing-green dial and a hand-wound chronograph movement finished with Côtes de Genève.', 'MANUAL', 42.00, 'Titanium', 50, 'Sapphire', 'Perforated Leather', 'Green', 'Titanium', 'MEN', 36, 318000.00, 318000.00, 0.00, 'ACTIVE', FALSE, TRUE, FALSE, 6, TIMESTAMPADD(DAY, -8, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6)),
((SELECT id FROM brands WHERE slug='maison-verac'), (SELECT id FROM categories WHERE slug='chronograph'), 'Quartz Chrono 39', 'maison-verac-quartz-chrono-39', 'QC-39', 'VER-QC39', 'A sporty, grab-and-go quartz chronograph.', 'The Quartz Chrono 39 offers 1/10th-second timing in a comfortable 39 mm case, with a sunburst blue dial and a soft FKM rubber strap.', 'QUARTZ', 39.00, 'Stainless Steel', 100, 'Sapphire', 'Rubber', 'Blue', 'Steel', 'UNISEX', 24, 54000.00, 45900.00, 15.00, 'ACTIVE', FALSE, FALSE, FALSE, 19, TIMESTAMPADD(DAY, -150, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6)),
((SELECT id FROM brands WHERE slug='kestrel'), (SELECT id FROM categories WHERE slug='pilot-field'), 'Pilot Mk IV 41', 'kestrel-pilot-mk-iv-41', 'PM-41', 'KES-PM41', 'A bead-blasted aviation watch with anti-magnetic protection.', 'Designed to the original cockpit-instrument specification: high-contrast numerals, a triangle at twelve and a soft-iron inner cage that protects the movement from magnetism.', 'AUTOMATIC', 41.00, 'Bead-blasted Steel', 200, 'Sapphire', 'Leather', 'Black', 'Grey', 'MEN', 36, 128000.00, 128000.00, 0.00, 'ACTIVE', TRUE, FALSE, FALSE, 15, TIMESTAMPADD(DAY, -90, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6)),
((SELECT id FROM brands WHERE slug='kestrel'), (SELECT id FROM categories WHERE slug='gmt-travel'), 'Navigator GMT 40', 'kestrel-navigator-gmt-40', 'NG-40', 'KES-NG40', 'A true flyer GMT with a two-tone 24-hour bezel.', 'An independently adjustable local hour hand makes the Navigator GMT the frequent traveller''s companion. The bidirectional ceramic bezel tracks a third time zone.', 'AUTOMATIC', 40.00, 'Stainless Steel', 100, 'Sapphire', 'Steel Bracelet', 'Blue', 'Steel', 'MEN', 36, 176000.00, 158400.00, 10.00, 'ACTIVE', FALSE, FALSE, TRUE, 31, TIMESTAMPADD(DAY, -180, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6)),
((SELECT id FROM brands WHERE slug='halden'), (SELECT id FROM categories WHERE slug='dive'), 'Abyss 300 Diver 42', 'halden-abyss-300-diver-42', 'AB-42', 'HAL-AB42', 'An ISO 6425 certified 300 m professional diver.', 'Helium escape valve, ceramic unidirectional bezel and a lume plot that glows for eight hours: the Abyss 300 is built for saturation diving and beautiful enough for dry land.', 'AUTOMATIC', 42.00, 'Stainless Steel', 300, 'Sapphire', 'Rubber', 'Black', 'Steel', 'MEN', 36, 142000.00, 113600.00, 20.00, 'ACTIVE', TRUE, FALSE, TRUE, 46, TIMESTAMPADD(DAY, -240, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6)),
((SELECT id FROM brands WHERE slug='halden'), (SELECT id FROM categories WHERE slug='dive'), 'Fjord Diver 39 Bronze', 'halden-fjord-diver-39-bronze', 'FD-39B', 'HAL-FD39', 'A CuSn8 bronze diver that develops a unique patina.', 'Every Fjord Diver ages differently. The bronze case develops a warm patina over time, complemented by a deep fjord-green dial and a vintage-style leather strap.', 'AUTOMATIC', 39.00, 'Bronze', 200, 'Sapphire', 'Leather', 'Green', 'Bronze', 'UNISEX', 36, 118000.00, 94400.00, 20.00, 'ACTIVE', FALSE, TRUE, FALSE, 9, TIMESTAMPADD(DAY, -15, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6)),
((SELECT id FROM brands WHERE slug='halden'), (SELECT id FROM categories WHERE slug='dive'), 'Lagoon Quartz Diver 36', 'halden-lagoon-quartz-diver-36', 'LQ-36', 'HAL-LQ36', 'A compact 200 m quartz diver with a turquoise dial.', 'A smaller diver with full professional credentials: 200 m water resistance, screw-down crown and a turquoise sunray dial that recalls tropical lagoons.', 'QUARTZ', 36.00, 'Stainless Steel', 200, 'Sapphire', 'Steel Bracelet', 'Turquoise', 'Steel', 'WOMEN', 24, 46000.00, 41400.00, 10.00, 'ACTIVE', FALSE, FALSE, FALSE, 22, TIMESTAMPADD(DAY, -110, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6)),
((SELECT id FROM brands WHERE slug='sora-tokei'), (SELECT id FROM categories WHERE slug='everyday'), 'Shizuka 38', 'sora-tokei-shizuka-38', 'SZ-38', 'SOR-SZ38', 'A textured ice-blue dial inspired by winter mornings in Nagano.', 'The Shizuka''s dial is stamped with a pattern evoking fresh snow. A slim integrated bracelet and 70-hour automatic movement make it an effortless daily companion.', 'AUTOMATIC', 38.00, 'Stainless Steel', 100, 'Sapphire', 'Steel Bracelet', 'Ice Blue', 'Steel', 'UNISEX', 24, 38500.00, 38500.00, 0.00, 'ACTIVE', FALSE, FALSE, TRUE, 64, TIMESTAMPADD(DAY, -330, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6)),
((SELECT id FROM brands WHERE slug='sora-tokei'), (SELECT id FROM categories WHERE slug='gmt-travel'), 'Kumo GMT 40 Titanium', 'sora-tokei-kumo-gmt-40', 'KG-40', 'SOR-KG40', 'A featherweight titanium GMT with a cloud-grey dial.', 'Crafted from scratch-resistant hardened titanium, the Kumo GMT weighs just 82 g on its bracelet. A 24-hour hand tracks home time in vivid orange.', 'AUTOMATIC', 40.00, 'Titanium', 200, 'Sapphire', 'Titanium Bracelet', 'Grey', 'Titanium', 'MEN', 36, 89000.00, 80100.00, 10.00, 'ACTIVE', TRUE, TRUE, FALSE, 12, TIMESTAMPADD(DAY, -5, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6)),
((SELECT id FROM brands WHERE slug='sora-tokei'), (SELECT id FROM categories WHERE slug='everyday'), 'Hana Solar 32', 'sora-tokei-hana-solar-32', 'HS-32', 'SOR-HS32', 'A solar-powered 32 mm watch with a mother-of-pearl dial.', 'Light-powered and never needing a battery change, the Hana Solar features a natural mother-of-pearl dial with rose-gold accents. A full charge runs for six months in darkness.', 'SOLAR', 32.00, 'Stainless Steel', 100, 'Sapphire', 'Leather', 'Mother of Pearl', 'Rose Gold', 'WOMEN', 24, 32000.00, 27200.00, 15.00, 'ACTIVE', FALSE, TRUE, FALSE, 17, TIMESTAMPADD(DAY, -3, CURRENT_TIMESTAMP(6)), CURRENT_TIMESTAMP(6));
